import assert from 'node:assert/strict';

export async function runMotionKeySmoke(page){
 const previous=await page.evaluate(()=>({project:JSON.stringify(project),curPage,curSec,curEl,curPane,selection,secFocus,mode:NAGWEB_STORY_EDITOR.canvasMode(),timeline:NAGWEB_STORY_TIMELINE_UI.state()}));
 try{
  await page.evaluate(()=>{project.pages[0].sections=[mkSection({layout:'free',sdEnabled:false,elements:[]})];curPage=0;curSec=0;curEl=0;selection=[];secFocus=false;saveProject();renderPane();renderPreview();history=[];future=[];});
  const before=await page.evaluate(()=>({project:JSON.stringify(project),stored:localStorage.getItem(STORE_KEY),factory:NAGWEB_MOTION_LAB.create().scene.elements}));
  async function frame(){await page.waitForFunction(()=>document.querySelector('.nw-motion-dialog iframe')?.contentDocument?.querySelector('.im-hov[data-motion-canvas]'));return (await page.$('.nw-motion-dialog iframe')).contentFrame();}
  async function select(f,selector){const n=await f.$(selector);await n.focus();await page.keyboard.press('Space');return n.evaluate(n=>n.dataset.id);}
  async function moment(at){const id=await page.$eval('[data-motion-key]',(n,at)=>[...n.options].find(o=>o.textContent===at+'%')?.value,at);assert.ok(id,'Moment '+at+' exists');await page.select('[data-motion-key]',id);return id;}
  async function change(key,value){await page.$eval('[data-motion-key-property="'+key+'"]',(n,v)=>{n.value=String(v);n.dispatchEvent(new Event('change',{bubbles:true}));},value);}
  async function pose(id){return page.evaluate(id=>{const f=document.querySelector('.nw-motion-dialog iframe'),d=f.contentDocument,n=d.querySelector('[data-id="'+id+'"]'),sid=d.querySelector('.sc').dataset.id;return {z:n.style.getPropertyValue('--nw-sd-z'),rx:n.style.getPropertyValue('--nw-sd-rx'),ry:n.style.getPropertyValue('--nw-sd-ry'),matrix:f.contentWindow.getComputedStyle(n).transform,x:n.style.left,y:n.style.top,w:n.style.width,progress:f.contentWindow.__NAG_SCROLL_DIRECTOR[sid].progress()};},id);}
  await page.click('.tb-left [data-motion-open]');let f=await frame();assert.equal(await page.$eval('[data-motion-key-panel]',n=>n.hidden),true);
  const id=await select(f,'.im-hov');assert.equal(await page.$eval('[data-motion-key-panel]',n=>n.hidden),false);assert.equal(await page.$eval('[data-motion-key]',n=>n.options.length),4);
  const ids=await page.$$eval('[data-motion-key] option',ns=>ns.map(n=>n.value));const first=await moment(0),original=await pose(id);
  await change('z',-240);await change('rotateX',18);await change('rotateY',-24);
  const prepared=await pose(id);assert.deepEqual([prepared.z,prepared.rx,prepared.ry],['-240.00px','18.00deg','-24.00deg']);assert.notEqual(prepared.matrix,original.matrix,'Edited depth produces a rendered transform');assert.deepEqual([prepared.x,prepared.y,prepared.w],[original.x,original.y,original.w]);assert.equal(prepared.progress,0);
  await moment(35);assert.deepEqual(await page.$$eval('[data-motion-key-property]',ns=>ns.map(n=>n.valueAsNumber)),[0,0,0],'Other moments stay intact');await moment(0);assert.equal(await page.$eval('[data-motion-key]',n=>n.value),first);
  await select(f,'.hd');assert.equal(await page.$eval('[data-motion-key-panel]',n=>n.hidden),true);assert.equal(await page.$$eval('[data-motion-key-property]',ns=>ns.every(n=>n.disabled)),true);await select(f,'[data-id="'+id+'"]');
  await page.click('[data-motion-template="soft-orbit"]');await page.waitForFunction(()=>document.querySelector('.nw-motion-dialog iframe')?.contentDocument?.querySelector('.hd')?.textContent==='Diseño en movimiento.');await page.click('[data-motion-template="iso-focus"]');await page.waitForFunction(id=>document.querySelector('.nw-motion-dialog iframe')?.contentDocument?.querySelector('[data-id="'+id+'"].nw-motion-selected'),{},id);assert.deepEqual(await page.$$eval('[data-motion-key-property]',ns=>ns.map(n=>n.valueAsNumber)),[-240,18,-24]);
  assert.equal(await page.evaluate(()=>JSON.stringify(project)),before.project);assert.equal(await page.evaluate(()=>localStorage.getItem(STORE_KEY)),before.stored);assert.equal(await page.evaluate(()=>history.length),0);
  await page.click('[data-motion-insert-group]');
  const inserted=await page.evaluate(id=>({project:JSON.stringify(project),group:sec().elements.find(e=>e.nwMotionInstance),element:sec().elements.find(e=>e.id===id),images:sec().elements.filter(e=>e.type==='image')}),id);
  const withoutIds=keys=>keys.map(({id,...key})=>key),expected=withoutIds(before.factory[0].sdKeyframes);expected[0]={...expected[0],z:-240,rotateX:18,rotateY:-24};assert.deepEqual(withoutIds(inserted.element.sdKeyframes),expected);assert.deepEqual(inserted.element.sdKeyframes.map(k=>k.id),ids);for(let i=1;i<3;i++)assert.deepEqual(withoutIds(inserted.images[i].sdKeyframes),withoutIds(before.factory[i].sdKeyframes));
  await page.evaluate(()=>undo());assert.equal(await page.evaluate(()=>JSON.stringify(project)),before.project);await page.evaluate(()=>redo());assert.equal(await page.evaluate(()=>JSON.stringify(project)),inserted.project);
  await page.evaluate(gid=>NAGWEB_MOTION_LAB.edit(gid),inserted.group.id);f=await frame();await select(f,'[data-id="'+id+'"]');await moment(0);await change('z',-180);assert.equal((await pose(id)).z,'-180.00px');await page.click('[data-motion-save]');
  const saved=await page.evaluate(id=>({project:JSON.stringify(project),element:sec().elements.find(e=>e.id===id),groups:sec().elements.filter(e=>e.nwMotionInstance).length}),id);assert.equal(saved.groups,1);const finalElement=JSON.parse(JSON.stringify(inserted.element));finalElement.sdKeyframes[0].z=-180;assert.deepEqual(saved.element,finalElement);
  await page.evaluate(gid=>NAGWEB_MOTION_LAB.edit(gid),inserted.group.id);f=await frame();await select(f,'[data-id="'+id+'"]');await moment(0);await change('rotateY',40);await page.click('[data-motion-close]');assert.equal(await page.evaluate(()=>JSON.stringify(project)),saved.project);
  await page.evaluate(()=>undo());assert.equal(await page.evaluate(()=>JSON.stringify(project)),inserted.project);await page.evaluate(()=>redo());assert.equal(await page.evaluate(()=>JSON.stringify(project)),saved.project);
  await page.evaluate(()=>{const f=document.createElement('iframe');f.id='key-export';f.srcdoc=generateSite(flattenPage(page()),false,false,false);document.body.append(f);});await page.waitForFunction(gid=>document.querySelector('#key-export')?.contentWindow?.__NAG_SCROLL_DIRECTOR?.[gid],{},inserted.group.id);
  const exported=await page.evaluate(({id,gid})=>{const f=document.querySelector('#key-export');f.contentWindow.__NAG_SCROLL_DIRECTOR[gid].set(0);const n=f.contentDocument.querySelector('[data-id="'+id+'"]');return ['z','rx','ry'].map(k=>n.style.getPropertyValue('--nw-sd-'+k));},{id,gid:inserted.group.id});assert.deepEqual(exported,['-180.00px','18.00deg','-24.00deg']);
  // Fractional moments in the tunnel must not be rounded to the next integer.
  await page.click('.tb-left [data-motion-open]');await page.click('[data-motion-template="card-tunnel"]');await page.waitForFunction(()=>document.querySelector('.nw-motion-dialog iframe')?.contentDocument?.querySelector('.hd')?.textContent==='Una nueva perspectiva.');f=await frame();const tunnelId=await select(f,'.im-hov');await moment(99.9);assert.equal(await page.$eval('[data-motion-progress]',n=>n.value),'99.9');assert.ok(Math.abs((await pose(tunnelId)).progress-.999)<1e-12);await change('z',-123);assert.equal((await pose(tunnelId)).z,'-123.00px');await page.click('[data-motion-close]');assert.equal(await page.evaluate(()=>JSON.stringify(project)),saved.project);
  console.log('Momentos Motion Lab: profundidad/inclinaciones visibles, mismo runtime, puntos e IDs conservados, otros elementos intactos, borradores, inserción/guardado/cancelar, historial, exportación y momentos decimales OK');
 }finally{
  await page.evaluate(p=>{document.querySelector('.nw-motion-dialog').close();document.querySelector('#key-export')?.remove();clearTimeout(previewTimer);project=JSON.parse(p.project);curPage=p.curPage;curSec=p.curSec;curEl=p.curEl;curPane=p.curPane;selection=p.selection;secFocus=p.secFocus;history=[];future=[];NAGWEB_STORY_EDITOR.setCanvasMode(p.mode);NAGWEB_STORY_TIMELINE_UI.setState(p.timeline);saveProject();renderScenes();renderPane();renderPreview();},previous);
 }
}
